  const finalCandidate = Boolean(complete
    && finalTurn?.observedKind === 'candidate'
    && /^[a-f0-9]{64}$/.test(finalClaim ?? '')
    && finalTurn.sourceSha256 === finalClaim
    && savedHash(suppliedCaptures.at(-1)?.stdout) === finalClaim
    && sourceHash === finalClaim);

